const formatTime = sec => {const n=Math.max(0,Math.floor(sec)),h=Math.floor(n/3600),m=Math.floor((n%3600)/60),s=n%60;return [h,m,s].map(v=>String(v).padStart(2,'0')).join(':');};
const formatShort = sec => {const n=Math.max(0,Math.ceil(sec));return n >= 3600 ? formatTime(n): `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
