function renderActivityRow(a){const strength=isStrengthSport(a.sport),yoga=isYogaSport(a.sport),ys=yogaStats(a.yogaPoses),sum=strengthStats(a.exercises);const meta=a.type==='interval'?`${a.rounds||0} turnos · ${humanDuration(a.duration)}`:yoga?`${ys.completed}/${ys.planned} posturas · ${humanDuration(a.duration)}`:strength?`${sum.count} exercícios · ${sum.sets} séries · ${humanDuration(a.duration)}`:`${km(a.distanceMeters||0)} km · ${humanDuration(a.duration)}`;const unit=a.type==='interval'?`${a.rounds||0} turnos`:yoga?`${ys.completed} posturas`:strength?`${sum.sets} séries`:`${km(a.distanceMeters||0)} km`;return `<button class="activity-row" data-activity-id="${esc(a.id)}"><span class="activity-emoji">${esc(a.emoji||sportById(a.sport)[2])}</span><span class="activity-main"><strong>${esc(a.name||sportById(a.sport)[1])}</strong><small>${dateText(a.startedAt)} · ${meta}</small></span><span class="activity-side">${unit}<small>Ver detalhes ↗</small></span></button>`;}
