// Construtor de sequências de yoga: posturas, lados, duração e transição, sem GPS nem repetições.
function renderYogaSection(){const active=isYogaSport(trackedActivity?.sport||selectedSport);$('yoga-section').classList.toggle('hidden',!active);$('yoga-live-visual').classList.toggle('hidden',!active);if(!active)return;for(const id of ['track-map-panel','strength-live-visual','activity-config-grid','live-distance-card','live-speed-card','live-pace-card','goal-progress-section'])$(id).classList.add('hidden');const selected=$('yoga-pose-select').value;$('yoga-pose-select').innerHTML=YOGA_POSES.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('');if(YOGA_POSES.some(p=>p.id===selected))$('yoga-pose-select').value=selected;renderYogaPoseFields(false);renderYogaSequence();mostrarCreditosYoga();}
function renderYogaPoseFields(reset=true){const pose=yogaPoseById($('yoga-pose-select').value);if(!pose)return;$('yoga-side-field').classList.toggle('hidden',!pose.sides);if(reset)$('yoga-seconds').value=pose.seconds;$('yoga-hint').textContent=pose.hint;$('yoga-focus-preview').textContent=pose.focus.map(f=>YOGA_FOCUS[f]).join(' · ');}
function renderYogaSequence(){const items=yogaEntries(),stats=yogaStats(items);$('yoga-count').textContent=`${stats.planned} postura(s) · ${humanDuration(stats.plannedSeconds)} planejados · ${stats.completed} concluída(s)`;$('yoga-flow-list').innerHTML=items.length?items.map((p,i)=>`<div class="yoga-flow-row ${p.completed?'yoga-completed':''}"><div class="yoga-flow-number">${p.completed?'✓':i+1}</div><div class="yoga-flow-thumb">${yogaPoseFoto(p.id,p.name)}</div><div class="yoga-flow-info"><strong>${esc(p.name)}${p.side?` · ${esc(p.side)}`:''}</strong><small>${formatShort(p.seconds)} na postura · ${formatShort(p.transition)} de transição</small></div><div class="yoga-flow-actions"><button class="icon-btn" data-yoga-up="${i}" title="Subir postura" aria-label="Subir postura" ${i===0||!!trackedActivity?'disabled':''}>↑</button><button class="icon-btn" data-yoga-down="${i}" title="Descer postura" aria-label="Descer postura" ${i===items.length-1||!!trackedActivity?'disabled':''}>↓</button><button class="icon-btn" data-yoga-remove="${i}" title="Remover postura" aria-label="Remover postura" ${!!trackedActivity?'disabled':''}>×</button></div></div>`).join(''):'<p class="helper-text">Escolha uma postura ou carregue uma sequência pronta para começar.</p>';$('yoga-flow-start').disabled=!trackedActivity||trackedActivity.status!=='running'||!items.some(p=>!p.completed)||!!yogaTimer;$('yoga-live-count').textContent=`${stats.completed} de ${stats.planned} posturas concluídas · ${humanDuration(stats.seconds)} de prática registrada`;$('yoga-live-focus').innerHTML=stats.focus.map(f=>`<span class="yoga-focus-chip">${YOGA_FOCUS[f]}</span>`).join('')||'<span class="helper-text">Selecione posturas para ver os objetivos da prática.</span>';}
$('yoga-pose-select').addEventListener('change',()=>renderYogaPoseFields());
$('yoga-add-pose').addEventListener('click',()=>{if(trackedActivity){toast('A sequência deve ser montada antes de iniciar a sessão.','error');return;}const pose=yogaPoseById($('yoga-pose-select').value),seconds=Number($('yoga-seconds').value),transition=Number($('yoga-transition').value);if(!pose||!Number.isInteger(seconds)||seconds<5||seconds>3600||!Number.isInteger(transition)||transition<0||transition>600){toast('Informe duração entre 5 e 3600 s e transição de até 600 s.','error');return;}yogaDraft.push({id:pose.id,name:pose.name,side:pose.sides?$('yoga-side').value:'',seconds,transition,completed:false});renderYogaSequence();toast('Postura adicionada à sequência.');});
$('yoga-presets').addEventListener('click',e=>{const btn=e.target.closest('[data-yoga-preset]');if(!btn||trackedActivity)return;const ids=YOGA_PRESETS[btn.dataset.yogaPreset];if(!ids)return;if(yogaDraft.length&&!confirm('Substituir a sequência atual pela prática sugerida?'))return;yogaDraft=ids.map(id=>{const p=yogaPoseById(id);return {id,name:p.name,side:p.sides?'Lado direito':'',seconds:p.seconds,transition:15,completed:false};});if(btn.dataset.yogaPreset==='matinal'){const i=yogaDraft.findIndex(p=>p.id==='guerreiro2');if(i>=0)yogaDraft.splice(i+1,0,{...yogaDraft[i],side:'Lado esquerdo'});const j=yogaDraft.findIndex(p=>p.id==='arvore');if(j>=0)yogaDraft.splice(j+1,0,{...yogaDraft[j],side:'Lado esquerdo'});}renderYogaSequence();toast('Sequência de yoga carregada.');});
$('yoga-flow-list').addEventListener('click',e=>{if(trackedActivity)return;const b=e.target.closest('[data-yoga-remove],[data-yoga-up],[data-yoga-down]');if(!b)return;const entries=yogaDraft;const remove=b.dataset.yogaRemove;if(remove!==undefined){entries.splice(+remove,1);}else{const up=b.dataset.yogaUp!==undefined,from=Number(up?b.dataset.yogaUp:b.dataset.yogaDown),to=from+(up?-1:1);if(to>=0&&to<entries.length)[entries[from],entries[to]]=[entries[to],entries[from]];}renderYogaSequence();});
function openYogaFlow(){if(!trackedActivity||trackedActivity.sport!=='yoga'||trackedActivity.status!=='running'){toast('Inicie ou retome a sessão de yoga antes da sequência.','error');return;}if(yogaTimer)return;const items=yogaEntries(),index=items.findIndex(p=>!p.completed);if(index<0){toast('Todas as posturas da sequência já foram concluídas.');return;}const pose=items[index];yogaTimer={status:'ready',index,phase:'pose',remainingMs:pose.seconds*1000,phaseDuration:pose.seconds,phaseEnd:0};$('yoga-timer-dialog').showModal();renderYogaTimer();}
function startYogaFlow(){const t=yogaTimer;if(!t||t.status!=='ready')return;unlockAudio();t.status='running';t.phaseEnd=Date.now()+t.remainingMs;announce(`Comece ${yogaEntries()[t.index].name}.`,'round_start');renderYogaTimer();}
function pauseYogaFlow(){const t=yogaTimer;if(!t||t.status!=='running')return;t.remainingMs=Math.max(0,t.phaseEnd-Date.now());t.status='paused';renderYogaTimer();}
function resumeYogaFlow(){const t=yogaTimer;if(!t||t.status!=='paused'||trackedActivity?.status!=='running'){toast('Retome a sessão principal antes da sequência.','error');return;}unlockAudio();t.status='running';t.phaseEnd=Date.now()+t.remainingMs;renderYogaTimer();}
function closeYogaFlow(silent=false){yogaTimer=null;if($('yoga-timer-dialog').open)$('yoga-timer-dialog').close();renderYogaSequence();if(!silent)toast('Cronômetro fechado. A sessão de yoga permanece ativa.');}
function nextYogaPose(skipped=false){const t=yogaTimer;if(!t)return;const items=yogaEntries(),pose=items[t.index];if(!pose)return;if(t.phase==='pose'){if(!skipped){pose.completed=true;pose.completedSeconds=pose.seconds;}else{pose.skipped=true;}if(trackedActivity)saveRuntime(true);}const next=items.findIndex((p,i)=>i>t.index&&!p.completed);if(next<0){t.status='done';t.remainingMs=0;renderYogaSequence();renderYogaTimer();announce('Sequência de yoga concluída!','complete');return;}if(t.phase==='pose'&&!skipped&&pose.transition>0){t.phase='transition';t.nextIndex=next;t.phaseDuration=pose.transition;t.remainingMs=pose.transition*1000;announce('Postura concluída. Prepare a transição.','round_end');}else{t.index=next;t.phase='pose';t.phaseDuration=items[next].seconds;t.remainingMs=items[next].seconds*1000;announce(`Próxima postura: ${items[next].name}.`,'round_start');}if(t.status==='running')t.phaseEnd=Date.now()+t.remainingMs;renderYogaSequence();renderYogaTimer();}
function tickYogaFlow(){const t=yogaTimer;if(!t||t.status!=='running')return;let count=0;while(yogaTimer===t&&t.status==='running'&&Date.now()>=t.phaseEnd&&count++<80){if(t.phase==='transition'){t.index=t.nextIndex;t.phase='pose';t.phaseDuration=yogaEntries()[t.index].seconds;t.remainingMs=t.phaseDuration*1000;announce(`Próxima postura: ${yogaEntries()[t.index].name}.`,'round_start');t.phaseEnd+=t.remainingMs;}else{const oldEnd=t.phaseEnd;nextYogaPose(false);if(t.status==='running')t.phaseEnd=oldEnd+t.remainingMs;}}renderYogaTimer();}
function renderYogaTimer(){const t=yogaTimer;if(!t)return;const poses=yogaEntries(),pose=poses[t.index],remaining=t.status==='running'?Math.max(0,t.phaseEnd-Date.now()):t.remainingMs;$('yoga-timer-pose').textContent=t.status==='done'?'Sequência concluída':t.phase==='transition'?'Prepare a próxima postura':pose.name+(pose.side?' · '+pose.side:'');$('yoga-timer-hint').textContent=t.status==='done'?'Prática registrada no seu treino.':t.phase==='transition'?'Respire e acomode o corpo antes da próxima postura.':yogaPoseById(pose.id)?.hint||'Respeite seus limites e respire naturalmente.';$('yoga-timer-phase').textContent=t.status==='done'?'CONCLUÍDO':t.phase==='transition'?'TRANSIÇÃO':'POSTURA';$('yoga-timer-remaining').textContent=t.status==='done'?'00:00':formatShort(Math.ceil(remaining/1000));$('yoga-timer-index').textContent=`Postura ${t.index+1} de ${poses.length}`;$('yoga-timer-progress').style.width=`${clamp(yogaStats(poses).completed/Math.max(1,poses.length)*100,0,100)}%`;const ring=$('yoga-timer-ring');ring.parentElement.classList.toggle('rest',t.phase==='transition');ring.style.strokeDashoffset=String(710*(1-clamp(remaining/Math.max(1,t.phaseDuration*1000),0,1)));$('yoga-timer-start').classList.toggle('hidden',t.status!=='ready');$('yoga-timer-pause').classList.toggle('hidden',t.status!=='running');$('yoga-timer-resume').classList.toggle('hidden',t.status!=='paused');$('yoga-timer-skip').classList.toggle('hidden',t.status==='ready'||t.status==='done');$('yoga-timer-close').textContent=t.status==='done'?'Voltar ao treino':'Fechar cronômetro';}
$('yoga-flow-start').addEventListener('click',openYogaFlow);
$('yoga-timer-start').addEventListener('click',startYogaFlow);
$('yoga-timer-pause').addEventListener('click',pauseYogaFlow);
$('yoga-timer-resume').addEventListener('click',resumeYogaFlow);
$('yoga-timer-skip').addEventListener('click',()=>{if(yogaTimer?.phase==='transition'){const t=yogaTimer;t.index=t.nextIndex;t.phase='pose';t.phaseDuration=yogaEntries()[t.index].seconds;t.remainingMs=t.phaseDuration*1000;if(t.status==='running')t.phaseEnd=Date.now()+t.remainingMs;renderYogaTimer();}else nextYogaPose(true);});
