// Registro de séries e repetições por exercício, com variantes e carga opcional.
function renderStrengthSection(){const mode=trackedActivity?.sport||selectedSport;const active=isStrengthSport(mode);$('strength-section').classList.toggle('hidden',!active);$('strength-live-visual').classList.toggle('hidden',!active);$('track-map-panel').classList.toggle('hidden',active);$('activity-config-grid').classList.toggle('hidden',active);$('live-distance-card').classList.toggle('hidden',active);$('live-speed-card').classList.toggle('hidden',active);$('live-pace-card').classList.toggle('hidden',active);$('goal-progress-section').classList.toggle('hidden',active);if(!active)return;const search=$('exercise-search').value.trim().toLocaleLowerCase('pt-BR');const list=EXERCISES.filter(e=>e.types.includes(mode)&&(e.name+' '+(e.variants||[]).join(' ')).toLocaleLowerCase('pt-BR').includes(search));const previous=$('exercise-select').value;$('exercise-select').innerHTML=list.length?list.map(e=>`<option value="${e.id}">${esc(e.name)}${e.kind==='cardio'?' • aeróbico':''}</option>`).join(''):'<option value="">Nenhum exercício encontrado</option>';if(list.some(e=>e.id===previous))$('exercise-select').value=previous;renderExerciseVariants();renderStrengthLog();}
function renderExerciseVariants(){const exercise=exerciseById($('exercise-select').value);const before=$('exercise-variant').value;$('exercise-variant').innerHTML=exercise?exercise.variants.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join(''):'';if(exercise?.variants.includes(before))$('exercise-variant').value=before;setDefaultExerciseMeasure();}
function setDefaultExerciseMeasure(){const exercise=exerciseById($('exercise-select').value),variant=$('exercise-variant').value||'';const dynamicDragon=exercise?.id==='dragon_flag'&&/dinâmica/i.test(variant);$('exercise-measure').value=exercise?.kind==='cardio'?'cardio':!dynamicDragon&&(exercise?.mode==='time'||/isom[eé]tric|sustentação/i.test(variant))?'time':'reps';updateExerciseMeasureFields();}
